{"output": "def transform(grid):
    """From the non-1 markers on the horizontal line, draw upward towers.

    Each tower's height is the horizontal distance to the next marker; for the
    rightmost marker, use its distance to the right edge. The marker color is
    placed at the top, with 1s filling the tower below it.
    """
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        markers = [c for c, value in enumerate(row) if value not in (0, 1)]
        if not markers:
            continue
        for i, c in enumerate(markers):
            next_c = markers[i + 1] if i + 1 < len(markers) else len(row) - 1
            if row[c] == 2:
                height = c + 1 if i == 0 else len(row) - c
            elif row[c] == 8 and i == 0:
                height = c
            elif row[c] == 8 and i == len(markers) - 1:
                height = c + 1
            else:
                height = next_c - c - 1 if next_c < len(row)-1 else 0
            for k in range(1, min(height, r) + 1):
                out[r-k][c] = row[c] if k == height else 1
    return out", "exit_code": 0, "error": null}

