 "content": "def transform(grid):
    """Draw upward bars from the marked row, using adjacent 1-run lengths.

    A 2's bar is one cell taller than its longest adjoining run of 1s; an 8's
    bar matches its longest adjoining run. The marker color caps each bar.
    """
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value not in (2, 8):
                continue
            left = c - 1
            while left >= 0 and row[left] == 1:
                left -= 1
            right = c + 1
            while right < len(row) and row[right] == 1:
                right += 1
            run = max(c - left - 1, right - c - 1)
            height = run + (1 if value == 2 else 0)
            for k in range(1, min(height, r) + 1):
                out[r-k][c] = value if k == height else 1
    return out
