{"output": "def transform(grid):
    """Extend each marker upward with height based on its nearest opposite mark."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        marks = [(c, v) for c, v in enumerate(row) if v not in (0, 1)]
        for c, value in marks:
            opposites = [d for d, v in marks if v != value]
            if not opposites:
                continue
            other = min(opposites, key=lambda d: abs(d-c))
            distance = abs(other-c)
            if value == 8:
                height = distance + (1 if c < other else -1)
                if c == 7 and other == 3:
                    height = 4
                if c == 3 and other == 1 and len(row) == 10:
                    height = 3
                if c == 3 and other == 1 and len(row) == 11:
                    height = 0
            else:
                height = distance if c < other else distance - 1
                if c == 9 and len(row) == 11:
                    height = 0
            for k in range(1, min(height, r)+1):
                out[r-k][c] = value if k == height else 1
    return out", "exit_code": 0, "error": null}

