    """Build upward bars whose heights are read from adjacent 1-runs."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value not in (2, 8):
                continue
            left = c - 1
            while left >= 0 and row[left] == 1:
                left -= 1
            right = c + 1
            while right < len(row) and row[right] == 1:
                right += 1
            run = max(c - left - 1, right - c - 1)
            height = run + (1 if value == 2 else 0)
            drawn_height = min(height, r)
            for k in range(1, drawn_height + 1):
                out[r-k][c] = value if k == drawn_height else 1
    return out
