 "content": "def transform(grid):
    """Extend each 2 or 8 upward to its color's standard tower height."""
    out = [row[:] for row in grid]
    heights = {2: 4, 8: 3}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value not in heights:
                continue
            height = min(heights[value], r)
            for k in range(1, height + 1):
                out[r - k][c] = value if k == height else 1
    return out
